import { createMemo, createSignal } from "my-solid";

const [path] = createSignal("/a?q=1");

// Like a router's `useLocation`: a getter over a memo, so reading `.search` in a component body is a reactive read.
export function useLocation() {
  const search = createMemo(() => path());
  return {
    get search() {
      return search();
    },
    get key() {
      return path();
    },
  };
}

export function Router(props) {
  return props.children;
}
